const AUTHOR_PHOTO = "";
// ---- 01-core.js
// هستهٔ پلاگین: وضعیت مشترک، رنگ، فونت و چیدمان راست‌به‌چپ

const S = {
  /** فونت هر وزن: { regular: {family, style}, ... } */
  fonts: {},
  family: TOKENS.font.family,
  /** متغیرها بر اساس نام کامل، مثل "bg-brand" یا "radius/md" */
  vars: {},
  varById: {},
  collections: {},
  icons: {},
  bankLogos: {},
  theme: "dark",
  stats: { variables: 0, components: 0, sets: 0, pages: 0, added: 0, updated: 0 },
};

/**
 * تایپوگرافی فقط با Variables (بدون Text style):
 * "Text sm/Semibold" → اندازه، ارتفاع خط، وزن و فونت هر کدام به متغیر وصل می‌شوند.
 */
const TYPE_WEIGHTS = { Regular: "regular", Medium: "medium", Semibold: "semibold", Bold: "bold" };
function typeSpec(name) {
  // Display: فونت عنوان، خط ۱٫۳۵ — Text: خط ۱٫۷۵ — Tight: فونت متن با خط ۱٫۳۵ (برچسب فیلد)
  // Control: خط ثابت ۲۰ پیکسل (متن کنار چک‌باکس و سوییچ)
  const m = /^(Display|Text|Tight|Control) ([0-9a-z]+)\/(\w+)$/.exec(name || "Text sm/Regular");
  if (!m) throw new Error(`Unknown type style: ${name}`);
  const kind = m[1].toLowerCase();
  const size = TOKENS.font.size[m[2]];
  const leading = kind === "text" ? TOKENS.font.leading.normal : kind === "control" ? 20 / size : TOKENS.font.leading.tight;
  return { kind, sizeKey: m[2], size, weight: TYPE_WEIGHTS[m[3]], leading };
}
const TYPE_SCALE = []
  .concat(["6xl", "5xl", "4xl", "3xl", "2xl", "xl"].map((k) => `Display ${k}`), ["xl", "lg", "md", "sm", "xs"].map((k) => `Text ${k}`));

/** جایگزین ?? (محیط اجرای پلاگین فیگما همهٔ نحوهای جدید را ندارد) */
const pick = (a, b) => (a === undefined || a === null ? b : a);

// ---------- رنگ ----------
const rgb = ([r, g, b]) => ({ r, g, b });
const paletteHex = (scale, step) => TOKENS.palette[scale === "brand" ? TOKENS.brandScale : scale][step];
function hexToRgba(h) {
  const s = h.replace("#", "");
  const n = (i) => parseInt(s.slice(i, i + 2), 16) / 255;
  return [n(0), n(2), n(4), 1];
}
/** مقدار واقعی یک توکن معنایی در تم */
function themeRgba(token, mode = S.theme) {
  const v = TOKENS.themes[mode][token];
  if (!v) throw new Error(`Unknown color token: ${token}`);
  return v.rgba ? v.rgba : hexToRgba(paletteHex(v.alias[0], v.alias[1]));
}

/**
 * رنگ برای fills و strokes:
 * "bg-brand" → متغیر تم؛ "firoozeh/500" → متغیر پالت؛ "#fff" یا [r,g,b,a] → رنگ ثابت.
 * opacity اختیاری روی خود paint اعمال می‌شود.
 */
function paint(c, opacity) {
  let rgba, variable;
  if (Array.isArray(c)) rgba = c;
  else if (c.startsWith("#")) rgba = hexToRgba(c);
  else if (c.includes("/")) {
    const [scale, step] = c.split("/");
    rgba = hexToRgba(paletteHex(scale, step));
    variable = S.vars[`color/${scale}/${step}`];
  } else {
    rgba = themeRgba(c);
    variable = S.vars[c];
  }
  let p = { type: "SOLID", color: rgb(rgba), opacity: pick(opacity, 1) * rgba[3] };
  if (variable) {
    // وقتی رنگ به متغیر وصل است، آلفا از خود متغیر می‌آید
    p = figma.variables.setBoundVariableForPaint({ type: "SOLID", color: rgb(rgba), opacity: pick(opacity, 1) }, "color", variable);
  }
  return p;
}

// ---------- فونت ----------
const WEIGHTS = ["light", "regular", "medium", "semibold", "bold", "black"];
const STYLE_ALIASES = {
  light: ["light"],
  regular: ["regular", "normal", "book", "roman"],
  medium: ["medium"],
  semibold: ["semibold", "demibold", "demi"],
  bold: ["bold"],
  black: ["black", "heavy", "extrabold"],
};
const norm = (s) => s.toLowerCase().replace(/[\s_-]/g, "");

/** وزن‌های فونت انتخابی را پیدا و بارگذاری می‌کند؛ وزن ناموجود به نزدیک‌ترین وزن می‌افتد */
async function loadFonts(family) {
  const all = await figma.listAvailableFontsAsync();
  const pick = (fam) => {
    const styles = all.filter((f) => norm(f.fontName.family) === norm(fam)).map((f) => f.fontName);
    if (!styles.length) return null;
    const found = {};
    for (const w of WEIGHTS) {
      found[w] = styles.find((f) => STYLE_ALIASES[w].includes(norm(f.style)));
    }
    return found.regular ? found : null;
  };
  let found = pick(family);
  let usedFamily = family;
  if (!found) {
    found = pick("Vazirmatn") || pick("Inter");
    usedFamily = found ? found.regular.family : "Inter";
  }
  if (!found) throw new Error("No usable font found");
  const order = ["regular", "medium", "semibold", "bold", "black", "light"];
  for (const w of WEIGHTS) {
    if (!found[w]) {
      // نزدیک‌ترین وزن موجود
      const i = order.indexOf(w);
      found[w] = [...order.slice(0, i).reverse(), ...order.slice(i)].map((x) => found[x]).find(Boolean);
    }
  }
  await Promise.all(Object.values(found).map((f) => figma.loadFontAsync(f)));
  S.fonts = found;
  S.family = usedFamily;
  return usedFamily;
}

// ---------- چیدمان ----------
/** تنظیم اندازهٔ فرزند داخل auto layout؛ بعد از append قابل اعمال است */
const SIZING = new WeakMap();
const ALIGN = { start: "MAX", center: "CENTER", end: "MIN", between: "SPACE_BETWEEN" };
const ALIGN_V = { start: "MIN", center: "CENTER", end: "MAX", between: "SPACE_BETWEEN" };
const CROSS_H = { start: "MAX", center: "CENTER", end: "MIN", baseline: "BASELINE" };
const CROSS_V = { start: "MIN", center: "CENTER", end: "MAX", baseline: "BASELINE" };

function bindNum(node, field, value) {
  const v = typeof value === "string" ? S.vars[value] : null;
  if (v) {
    try { node.setBoundVariable(field, v); return; } catch (e) { /* فیلد پشتیبانی نمی‌شود */ }
  }
  node[field] = typeof value === "string" ? numOf(value) : value;
}
/** مقدار عددی "space/4" یا "radius/md" */
function numOf(name) {
  const [group, key] = name.split("/");
  if (group === "space") return TOKENS.space[key];
  if (group === "radius") return TOKENS.radius[key];
  if (S.numbers[name] !== undefined) return S.numbers[name];
  throw new Error(`Unknown number token: ${name}`);
}
S.numbers = {};

function setRadius(node, r) {
  if (r === undefined) return;
  if (Array.isArray(r)) {
    // [شروع-بالا, پایان-بالا, پایان-پایین, شروع-پایین] منطقی؛ شروع = راست
    const [ss, se, ee, es] = r;
    bindNum(node, "topRightRadius", ss);
    bindNum(node, "topLeftRadius", se);
    bindNum(node, "bottomLeftRadius", ee);
    bindNum(node, "bottomRightRadius", es);
    return;
  }
  for (const f of ["topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius"]) bindNum(node, f, r);
}

/** ترکیب‌های سایه؛ هر جزء یک توکن افکت است که لایه‌هایش به متغیر وصل‌اند */
const EFFECT_COMBOS = {
  Button: ["shadow-xs", "shadow-skeuomorphic"],
  "Button focus": ["shadow-xs", "shadow-skeuomorphic", "ring-brand"],
  "Button danger focus": ["shadow-xs", "shadow-skeuomorphic", "ring-error"],
  "Input focus": ["shadow-xs", "ring-brand"],
  "Input error focus": ["shadow-xs", "ring-error"],
  Elevated: ["shadow-lg", "highlight"],
  // کارت و هشدار در CSS: سایهٔ xs به‌علاوهٔ خط روشن بالا
  Surface: ["shadow-xs", "highlight"],
  Dialog: ["shadow-2xl", "highlight"],
  Popover: ["shadow-xl", "highlight"],
  "highlight-only": ["highlight"],
  "Focus ring/brand": ["ring-brand"],
  "Focus ring/error": ["ring-error"],
};
function effectTokens(name) {
  if (EFFECT_COMBOS[name]) return EFFECT_COMBOS[name];
  const m = /^Shadow\/(\w+)$/.exec(name);
  if (m) return [`shadow-${m[1]}`];
  throw new Error(`Unknown effect: ${name}`);
}

/** سایه‌ها مستقیم روی گره، با رنگ، فاصله، محو و گسترش وصل به متغیرهای تم */
function effectStyle(node, name) {
  if (!name) return;
  const tokens = [].concat(name).flatMap(effectTokens);
  const out = [];
  for (const token of tokens) {
    for (const layer of EFFECT_LAYERS[token] || []) {
      const e = layer.value(S.theme);
      let fx = {
        type: layer.type, color: e.color, offset: { x: e.x, y: e.y }, radius: e.blur, spread: e.spread, visible: true, blendMode: "NORMAL",
      };
      if (layer.type === "DROP_SHADOW") fx.showShadowBehindNode = false;
      for (const [field, key] of [["color", "color"], ["offsetX", "x"], ["offsetY", "y"], ["radius", "blur"], ["spread", "spread"]]) {
        const v = layer.vars[key];
        if (v) { try { fx = figma.variables.setBoundVariableForEffect(fx, field, v); } catch (err) { /* API قدیمی */ } }
      }
      out.push(fx);
    }
  }
  node.effects = out;
}
/** لایه‌های هر توکن افکت؛ در buildVariables پر می‌شود */
const EFFECT_LAYERS = {};

/**
 * فریم با auto layout راست‌به‌چپ.
 * o: { name, dir: "H"|"V"|"none", gap, p, px, py, pt, pb, ps, pe, w, h, align, cross, fill, stroke, sw, radius, shadow, clip, wrap, opacity }
 * w/h: عدد = ثابت، "fill" = پرکردن والد، "hug" = به اندازهٔ محتوا (پیش‌فرض)
 */
function F(o = {}, children = []) {
  const f = figma.createFrame();
  f.name = o.name || "Frame";
  f.fills = o.fill ? [paint(o.fill, o.fillOpacity)] : [];
  f.clipsContent = !!o.clip;
  const dir = o.dir || "H";
  if (dir !== "none") {
    f.layoutMode = dir === "H" ? "HORIZONTAL" : "VERTICAL";
    if (o.wrap) f.layoutWrap = "WRAP";
    if (o.gap !== undefined) bindNum(f, "itemSpacing", o.gap);
    if (o.wrap && o.rowGap !== undefined) bindNum(f, "counterAxisSpacing", o.rowGap);
    const pad = (k, v) => v !== undefined && bindNum(f, k, v);
    const px = pick(o.px, o.p), py = pick(o.py, o.p);
    pad("paddingTop", pick(o.pt, py));
    pad("paddingBottom", pick(o.pb, py));
    // RTL: شروع = راست
    pad("paddingRight", pick(o.ps, px));
    pad("paddingLeft", pick(o.pe, px));
    if (dir === "H") {
      f.primaryAxisAlignItems = ALIGN[o.align || "start"];
      f.counterAxisAlignItems = CROSS_V[o.cross || "center"];
    } else {
      f.primaryAxisAlignItems = ALIGN_V[o.align || "start"];
      f.counterAxisAlignItems = CROSS_H[o.cross || "start"];
    }
  }
  if (o.stroke) {
    f.strokes = [paint(o.stroke, o.strokeOpacity)];
    f.strokeAlign = o.strokeAlign || "INSIDE";
    if (o.sides) {
      const [t, r, b, l] = o.sides;
      f.strokeTopWeight = t; f.strokeRightWeight = r; f.strokeBottomWeight = b; f.strokeLeftWeight = l;
    } else f.strokeWeight = pick(o.sw, 1);
    if (o.dash) f.dashPattern = o.dash;
  }
  setRadius(f, o.radius);
  effectStyle(f, o.shadow);
  if (o.opacity !== undefined) f.opacity = o.opacity;
  tagCss(f, o);

  // RTL: در فیگما ترتیب افقی چپ‌به‌راست است، پس فرزندان را برعکس می‌چینیم
  const kids = children.flat(Infinity).filter(Boolean);
  const ordered = dir === "H" ? kids.slice().reverse() : kids;
  for (const k of ordered) f.appendChild(k);
  sizeSelf(f, o, dir);
  if (dir !== "none") for (const k of kids) applySizing(k);
  else {
    // چیدمان آزاد: مختصات منطقی x از راست
    const W = typeof o.w === "number" ? o.w : 100;
    for (const k of kids) {
      const s = SIZING.get(k) || {};
      if (s.x !== undefined) k.x = W - s.x - k.width;
      if (s.y !== undefined) k.y = s.y;
    }
  }
  return f;
}

function sizeSelf(f, o, dir) {
  const W = o.w, H = o.h;
  if (dir === "none") {
    f.resize(typeof W === "number" ? W : 100, typeof H === "number" ? H : 100);
  } else {
    const fixedW = typeof W === "number" || (typeof W === "string" && S.vars[W]);
    const fixedH = typeof H === "number" || (typeof H === "string" && S.vars[H]);
    const horizontal = f.layoutMode === "HORIZONTAL";
    f.primaryAxisSizingMode = (horizontal ? fixedW : fixedH) ? "FIXED" : "AUTO";
    f.counterAxisSizingMode = (horizontal ? fixedH : fixedW) ? "FIXED" : "AUTO";
    if (fixedW || fixedH) {
      const w = typeof W === "number" ? W : fixedW ? numOf(W) : f.width;
      const h = typeof H === "number" ? H : fixedH ? numOf(H) : f.height;
      f.resize(Math.max(w, 0.01), Math.max(h, 0.01));
      if (typeof W === "string" && S.vars[W]) bindNum(f, "width", W);
      if (typeof H === "string" && S.vars[H]) bindNum(f, "height", H);
    }
    if (o.minW) f.minWidth = o.minW;
    if (o.minH) f.minHeight = o.minH;
    if (o.maxW) f.maxWidth = o.maxW;
  }
  SIZING.set(f, { w: W, h: H, x: o.x, y: o.y, absolute: o.absolute, grow: o.grow });
}

function applySizing(k) {
  const s = SIZING.get(k);
  if (!s) return;
  const parent = k.parent;
  if (!parent || parent.layoutMode === "NONE") return;
  if (s.absolute) {
    k.layoutPositioning = "ABSOLUTE";
    if (s.x !== undefined) k.x = parent.width - s.x - k.width;
    if (s.y !== undefined) k.y = s.y;
    return;
  }
  try {
    if (s.w === "fill") k.layoutSizingHorizontal = "FILL";
    else if (s.w === "hug" && (k.type === "TEXT" || k.layoutMode !== "NONE")) k.layoutSizingHorizontal = "HUG";
    if (s.h === "fill") k.layoutSizingVertical = "FILL";
    if (s.grow) k.layoutGrow = 1;
  } catch (e) { /* نوع گره اجازه نمی‌دهد */ }
}

/** متن فارسی؛ s: { style: "Text sm/Medium", color, align, w, maxLines, name } */
function T(text, o = {}) {
  const t = figma.createText();
  const spec = typeSpec(o.style);
  t.fontName = S.fonts[o.weight || spec.weight];
  t.fontSize = o.size || spec.size;
  t.lineHeight = { unit: "PIXELS", value: Math.round((o.size || spec.size) * (o.leading || spec.leading)) };
  t.characters = String(text);
  t.name = o.name || String(text).slice(0, 40);
  t.fills = [paint(o.color || "text-primary")];
  t.textAlignHorizontal = { start: "RIGHT", center: "CENTER", end: "LEFT", justify: "JUSTIFIED" }[o.align || "start"];
  if (o.ltr) t.textAlignHorizontal = o.align === "center" ? "CENTER" : "LEFT";
  t.textAutoResize = o.w === "fill" || typeof o.w === "number" ? "HEIGHT" : "WIDTH_AND_HEIGHT";
  if (typeof o.w === "number") t.resize(o.w, t.height);
  if (o.maxLines) { t.textTruncation = "ENDING"; t.maxLines = o.maxLines; }
  if (o.decoration) t.textDecoration = o.decoration;
  if (o.opacity !== undefined) t.opacity = o.opacity;
  if (o.highlight) t.setRangeFills(o.highlight[0], o.highlight[1], [paint("text-brand")]);
  if (o.letterSpacing) t.letterSpacing = { unit: "PERCENT", value: o.letterSpacing };
  if (!o.size && !o.weight && !o.leading) bindType(t, spec);
  tagCss(t, o);
  SIZING.set(t, { w: o.w, h: o.h, x: o.x, y: o.y, absolute: o.absolute, grow: o.grow });
  return t;
}

function bindType(node, spec) {
  const bind = (field, key) => {
    const v = S.vars[key];
    if (v) { try { node.setBoundVariable(field, v); } catch (e) { /* API قدیمی */ } }
  };
  bind("fontFamily", spec.kind === "display" ? "font/family/display" : "font/family/sans");
  bind("fontStyle", `font/weight/${spec.weight}`);
  bind("fontSize", `font/size/${spec.sizeKey}`);
  bind("lineHeight", spec.kind === "control" ? "font/line-height/control" : `font/line-height/${spec.kind === "tight" ? "display" : spec.kind}-${spec.sizeKey}`);
}

/** مستطیل/بیضی ساده */
function R(o = {}) {
  const r = o.ellipse ? figma.createEllipse() : figma.createRectangle();
  r.name = o.name || (o.ellipse ? "Dot" : "Rect");
  r.resize(pick(o.w, 8), pick(o.h, 8));
  r.fills = o.fill ? [paint(o.fill, o.fillOpacity)] : [];
  if (o.stroke) { r.strokes = [paint(o.stroke)]; r.strokeWeight = pick(o.sw, 1); r.strokeAlign = "INSIDE"; }
  if (!o.ellipse) setRadius(r, o.radius);
  if (o.ellipse && o.arc) r.arcData = o.arc;
  if (o.rotation) r.rotation = o.rotation;
  effectStyle(r, o.shadow);
  tagCss(r, o);
  SIZING.set(r, { w: o.fillW ? "fill" : undefined, h: o.fillH ? "fill" : undefined, x: o.x, y: o.y, absolute: o.absolute, grow: o.grow });
  return r;
}

/**
 * کلاس CSS متناظر برای تست هم‌خوانی پیکسلی (test/css-metrics.json).
 * css: "k-badge k-badge--success" — cssCheck: فهرست ویژگی‌هایی که مقایسه می‌شوند (پیش‌فرض همه به‌جز ارتفاع)
 */
function tagCss(node, o) {
  if (o.css) node.setPluginData("css", JSON.stringify({ key: o.css, check: o.cssCheck || null }));
}

/** جای خالی منعطف */
const Spacer = () => F({ name: "Spacer", grow: true, w: 1, h: 1 });

// ---------- ارقام فارسی ----------
const FA = "۰۱۲۳۴۵۶۷۸۹";
const fa = (v) => String(v).replace(/\d/g, (d) => FA[d]);
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

/** افزودن فرزند به فریم موجود با رعایت RTL و اندازه‌دهی */
function add(parent, ...kids) {
  for (const k of kids.flat(Infinity)) {
    if (!k) continue;
    if (parent.layoutMode === "HORIZONTAL" && parent.layoutWrap !== "WRAP") parent.insertChild(0, k);
    else parent.appendChild(k);
    applySizing(k);
  }
  return parent;
}

// ---- 02-variables.js
// متغیرها (Variables)، استایل‌های متن و افکت — همه از روی توکن‌های @kashi-ui/tokens

let existingVars = null;
let existingCollections = null;

async function getCollection(name, modes) {
  existingCollections = existingCollections || (await figma.variables.getLocalVariableCollectionsAsync());
  let c = existingCollections.find((x) => x.name === name);
  if (!c) c = figma.variables.createVariableCollection(name);
  // نام mode ها را یکی می‌کند و mode های کم را می‌سازد
  const ids = {};
  modes.forEach((m, i) => {
    if (c.modes[i]) {
      if (c.modes[i].name !== m) c.renameMode(c.modes[i].modeId, m);
      ids[m] = c.modes[i].modeId;
    } else {
      // پلن رایگان فیگما فقط یک mode دارد؛ بقیه را بی‌صدا رد می‌کنیم
      try { ids[m] = c.addMode(m); } catch (e) { S.limitedModes = true; }
    }
  });
  S.collections[name] = { node: c, modes: ids };
  return { c, ids };
}

/** مقدار برای mode؛ اگر mode ساخته نشده باشد (پلن رایگان) رد می‌شود */
function setVal(v, ids, mode, value) {
  if (ids[mode]) v.setValueForMode(ids[mode], value);
}

async function getVariable(c, name, type, scopes) {
  existingVars = existingVars || (await figma.variables.getLocalVariablesAsync());
  let v = existingVars.find((x) => x.name === name && x.variableCollectionId === c.id);
  if (!v) {
    v = figma.variables.createVariable(name, c, type);
    existingVars.push(v);
  }
  if (scopes) v.scopes = scopes;
  S.varById[v.id] = v;
  S.stats.variables++;
  return v;
}

const COLOR_SCOPES = {
  bg: ["FRAME_FILL", "SHAPE_FILL"],
  text: ["TEXT_FILL"],
  border: ["STROKE_COLOR"],
};
const rgbaObj = ([r, g, b, a]) => ({ r, g, b, a });

async function buildVariables() {
  existingVars = null;
  existingCollections = null;

  // ---- پالت
  const prim = await getCollection("Kashi · Primitives", ["Value"]);
  for (const [scale, steps] of Object.entries(TOKENS.palette)) {
    for (const [step, hex] of Object.entries(steps)) {
      const v = await getVariable(prim.c, `color/${scale}/${step}`, "COLOR", ["ALL_SCOPES"]);
      v.setValueForMode(prim.ids.Value, rgbaObj(hexToRgba(hex)));
      S.vars[`color/${scale}/${step}`] = v;
    }
  }
  // brand فقط نام مستعار است؛ برای عوض کردن رنگ برند این‌ها را به پالت دیگری وصل کنید
  for (const step of Object.keys(TOKENS.palette[TOKENS.brandScale])) {
    const v = await getVariable(prim.c, `color/brand/${step}`, "COLOR", ["ALL_SCOPES"]);
    v.setValueForMode(prim.ids.Value, figma.variables.createVariableAlias(S.vars[`color/${TOKENS.brandScale}/${step}`]));
    v.description = "رنگ برند — برای تغییر برند، این را به یک رنگ دیگر از پالت وصل کنید";
    S.vars[`color/brand/${step}`] = v;
  }

  // ---- تم تیره و روشن
  const theme = await getCollection("Kashi · Theme", S.theme === "light" ? ["Light", "Dark"] : ["Dark", "Light"]);
  for (const token of Object.keys(TOKENS.themes.dark)) {
    const scopes = COLOR_SCOPES[token.split("-")[0]] || ["ALL_SCOPES"];
    const v = await getVariable(theme.c, token.replace(/^(bg|text|border)-/, "$1/"), "COLOR", scopes);
    for (const [mode, key] of [["Dark", "dark"], ["Light", "light"]]) {
      const val = TOKENS.themes[key][token];
      setVal(v, theme.ids, mode, val.alias ? figma.variables.createVariableAlias(S.vars[`color/${val.alias[0]}/${val.alias[1]}`]) : rgbaObj(val.rgba));
    }
    S.vars[token] = v;
  }

  // ---- گردی گوشه‌ها با چهار حالت (همان --k-radius-factor)
  const radius = await getCollection("Kashi · Radius", ["Default", "Sharp", "Soft", "Round"]);
  const factors = { Default: 1, Sharp: 0, Soft: 0.5, Round: 1.75 };
  const radii = Object.assign({}, TOKENS.radius, { checkbox: 5 });
  for (const [k, base] of Object.entries(radii)) {
    const v = await getVariable(radius.c, `radius/${k}`, "FLOAT", ["CORNER_RADIUS"]);
    for (const [mode, f] of Object.entries(factors)) setVal(v, radius.ids, mode, k === "full" ? 9999 : base * f);
    S.vars[`radius/${k}`] = v;
    S.numbers[`radius/${k}`] = base;
  }

  // ---- فاصله‌ها
  const space = await getCollection("Kashi · Spacing", ["Value"]);
  for (const [k, val] of Object.entries(TOKENS.space)) {
    const v = await getVariable(space.c, `space/${k.replace(".", "_")}`, "FLOAT", ["GAP", "WIDTH_HEIGHT"]);
    v.setValueForMode(space.ids.Value, val);
    S.vars[`space/${k}`] = v;
  }

  // ---- تراکم: ارتفاع و فاصلهٔ داخلی کنترل‌ها (همان --k-density)
  const density = await getCollection("Kashi · Density", ["Default", "Compact", "Comfortable"]);
  const dens = { Default: 1, Compact: 0.875, Comfortable: 1.125 };
  const controls = {
    "control/height/xs": 28, "control/height/sm": 36, "control/height/md": 40, "control/height/lg": 44, "control/height/xl": 48,
    "control/padding/xs": 8, "control/padding/sm": 12, "control/padding/md": 14, "control/padding/lg": 18, "control/padding/xl": 20,
    "input/height/sm": 36, "input/height/md": 40, "input/height/lg": 44, "input/padding": 14,
    "card/padding/sm": 16, "card/padding/md": 24, "card/padding/lg": 32,
    "menu/item-height": 36, "tab/height": 40, "alert/padding": 16,
  };
  for (const [k, base] of Object.entries(controls)) {
    const v = await getVariable(density.c, k, "FLOAT", [k.includes("height") ? "WIDTH_HEIGHT" : "GAP"]);
    for (const [mode, f] of Object.entries(dens)) setVal(v, density.ids, mode, Math.round(base * f));
    S.vars[k] = v;
    S.numbers[k] = base;
  }

  // ---- تایپوگرافی؛ فونت دلخواه (حتی فونت پولی) با عوض کردن یک متغیر
  const typo = await getCollection("Kashi · Typography", ["Default", "Compact", "Large"]);
  const scales = { Default: 1, Compact: 0.9375, Large: 1.125 };
  const fam = await getVariable(typo.c, "font/family/sans", "STRING", ["FONT_FAMILY"]);
  const disp = await getVariable(typo.c, "font/family/display", "STRING", ["FONT_FAMILY"]);
  for (const mode of Object.keys(typo.ids)) {
    setVal(fam, typo.ids, mode, S.family);
    setVal(disp, typo.ids, mode, S.family);
  }
  fam.description = "نام فونت متن؛ هر فونتی که روی سیستم نصب است (مثل IRANSans یا Yekan Bakh)";
  S.vars["font/family/sans"] = fam;
  S.vars["font/family/display"] = disp;
  for (const w of WEIGHTS) {
    const v = await getVariable(typo.c, `font/weight/${w}`, "STRING", ["FONT_STYLE"]);
    for (const mode of Object.keys(typo.ids)) setVal(v, typo.ids, mode, S.fonts[w].style);
    S.vars[`font/weight/${w}`] = v;
  }
  for (const [k, size] of Object.entries(TOKENS.font.size)) {
    const v = await getVariable(typo.c, `font/size/${k}`, "FLOAT", ["FONT_SIZE"]);
    for (const [mode, f] of Object.entries(scales)) setVal(v, typo.ids, mode, Math.round(size * f));
    S.vars[`font/size/${k}`] = v;
    for (const [kind, leading] of [["text", TOKENS.font.leading.normal], ["display", TOKENS.font.leading.tight]]) {
      const lh = await getVariable(typo.c, `font/line-height/${kind}-${k}`, "FLOAT", ["LINE_HEIGHT"]);
      for (const [mode, f] of Object.entries(scales)) setVal(lh, typo.ids, mode, Math.round(size * f * leading));
      S.vars[`font/line-height/${kind}-${k}`] = lh;
    }
  }
  // خط ثابت متن کنار چک‌باکس، رادیو و سوییچ (1.25rem در CSS)
  const ctl = await getVariable(typo.c, "font/line-height/control", "FLOAT", ["LINE_HEIGHT"]);
  for (const [mode, f] of Object.entries(scales)) setVal(ctl, typo.ids, mode, Math.round(20 * f));
  S.vars["font/line-height/control"] = ctl;

  await buildEffectVariables();
}

// ---------- سایه‌ها به شکل متغیر ----------
/**
 * هر لایهٔ سایه پنج متغیر در مجموعهٔ تم دارد (رنگ، x، y، محو، گسترش) تا در تیره و روشن فرق کند.
 * لایه‌ای که در یک تم نیست، با رنگ شفاف پر می‌شود.
 */
async function buildEffectVariables() {
  const theme = S.collections["Kashi · Theme"];
  const tokens = Object.keys(TOKENS.effects.dark);
  for (const token of tokens) {
    const dark = TOKENS.effects.dark[token] || [];
    const light = TOKENS.effects.light[token] || [];
    const n = Math.max(dark.length, light.length);
    EFFECT_LAYERS[token] = [];
    for (let i = 0; i < n; i++) {
      const pickLayer = (mode) => (mode === "dark" ? dark : light)[i] || null;
      const type = (dark[i] || light[i]).type;
      const base = `effect/${token}/${i + 1}`;
      const vars = {
        color: await getVariable(theme.node, `${base}/color`, "COLOR", ["EFFECT_COLOR"]),
        x: await getVariable(theme.node, `${base}/x`, "FLOAT", ["EFFECT_FLOAT"]),
        y: await getVariable(theme.node, `${base}/y`, "FLOAT", ["EFFECT_FLOAT"]),
        blur: await getVariable(theme.node, `${base}/blur`, "FLOAT", ["EFFECT_FLOAT"]),
        spread: await getVariable(theme.node, `${base}/spread`, "FLOAT", ["EFFECT_FLOAT"]),
      };
      for (const [mode, key] of [["Dark", "dark"], ["Light", "light"]]) {
        const l = pickLayer(key) || { x: 0, y: 0, blur: 0, spread: 0, rgba: [0, 0, 0, 0] };
        setVal(vars.color, theme.modes, mode, rgbaObj(l.rgba));
        setVal(vars.x, theme.modes, mode, l.x);
        setVal(vars.y, theme.modes, mode, l.y);
        setVal(vars.blur, theme.modes, mode, l.blur);
        setVal(vars.spread, theme.modes, mode, l.spread);
      }
      EFFECT_LAYERS[token].push({
        type,
        vars,
        value: (mode) => {
          const l = pickLayer(mode) || { x: 0, y: 0, blur: 0, spread: 0, rgba: [0, 0, 0, 0] };
          return { color: rgbaObj(l.rgba), x: l.x, y: l.y, blur: l.blur, spread: l.spread };
        },
      });
    }
  }
}

/** استایل‌هایی که نسخه‌های قبلی پلاگین ساخته بودند؛ حالا همه‌چیز Variable است */
async function removeLegacyStyles() {
  let removed = 0;
  for (const st of await figma.getLocalTextStylesAsync()) {
    if (/^(Display|Text) [0-9a-z]+\/(Regular|Medium|Semibold|Bold)$/.test(st.name)) { st.remove(); removed++; }
  }
  for (const st of await figma.getLocalEffectStylesAsync()) {
    if (/^(Dark|Light)\/(Shadow\/|Focus ring\/|Skeuomorphic|Button|Input|Elevated|Popover)/.test(st.name)) { st.remove(); removed++; }
  }
  return removed;
}

// ---- 03-assets.js
// آیکون‌ها (از @kashi-ui/icons) و لوگوی بانک‌ها

// ICONS و ICON_TITLES را build.mjs از packages/icons/src/icons.js می‌گذارد

const svgOf = (inner, color = "#000") =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${inner}</svg>`;

/** صفحه‌های آیکون و لوگو؛ هر کدام کامپوننت با کلید ثابت تا در به‌روزرسانی‌ها instance ها وصل بمانند */
function buildAssets() {
  const root = kitPage("🧩", "Assets", "آیکون‌ها و لوگوها", "");
  section(root, "Icons · آیکون‌ها", `${fa(Object.keys(ICONS).length)} آیکون ۲۰×۲۰ با خط ۱٫۵، هم‌شکل آیکون‌های داخلی کاشی. در طرح‌ها با Instance swap عوض می‌شوند.`, buildIcons);
  section(root, "Bank logos · لوگوی بانک‌ها", `${fa(BANKS.length)} لوگوی بانک و درگاه پرداخت از @kashi-ui/bank-logos.`, buildBankLogos);
}

function buildIcons(holder) {
  for (const [name, inner] of Object.entries(ICONS)) {
    const node = figma.createNodeFromSvg(svgOf(inner));
    node.name = `Icon / ${name}`;
    const comp = upsertComponent(`Icon / ${name}`, node);
    comp.name = `Icon / ${name}`;
    comp.fills = [];
    comp.clipsContent = false;
    for (const n of comp.findAll(() => true)) {
      if ("constraints" in n) n.constraints = { horizontal: "SCALE", vertical: "SCALE" };
      if ("strokes" in n && n.strokes.length) n.strokes = [paint("text-secondary")];
    }
    comp.description = `${ICON_TITLES[name]} — ${name} · @kashi-ui/icons`;
    add(holder, F({ name, dir: "V", gap: 8, p: 12, cross: "center", w: 96, radius: "radius/md", stroke: "border-secondary", fill: "bg-secondary" }, [
      comp,
      T(name, { style: "Text xs/Regular", color: "text-tertiary", align: "center", ltr: true }),
    ]));
    S.icons[name] = comp;
  }
}

/** نمونهٔ آیکون با اندازه و رنگ دلخواه */
function I(name, size = 20, color = "text-tertiary") {
  const comp = S.icons[name] || S.icons.info;
  const inst = comp.createInstance();
  if (size !== 20) inst.rescale(size / 20);
  inst.name = name;
  for (const n of inst.findAll((x) => "strokes" in x && x.strokes.length)) n.strokes = [paint(color)];
  return inst;
}

/** لوگوی بانک‌ها به شکل کامپوننت؛ برای فیلد کارت، شبا و نشان بانک */
function buildBankLogos(holder) {
  for (const b of BANKS) {
    let node;
    try { node = figma.createNodeFromSvg(b.svg); } catch (e) { continue; }
    node.rescale(32 / Math.max(node.width, node.height));
    const comp = upsertComponent(`Bank / ${b.slug}`, node);
    comp.name = `Bank / ${b.slug}`;
    comp.description = b.name;
    comp.fills = [];
    add(holder, F({ name: b.slug, dir: "V", gap: 8, p: 12, cross: "center", w: 120, radius: "radius/md", stroke: "border-secondary", fill: "bg-secondary" }, [
      comp,
      T(b.name, { style: "Text xs/Regular", color: "text-secondary", align: "center", w: "fill" }),
    ]));
    S.bankLogos[b.slug] = comp;
  }
}

function bankLogo(slug, size = 20) {
  const comp = S.bankLogos[slug];
  if (!comp) return R({ w: size, h: size, radius: "radius/full", fill: "bg-tertiary", name: slug });
  const inst = comp.createInstance();
  inst.rescale(size / Math.max(comp.width, comp.height));
  return inst;
}
const bankName = (slug) => (BANKS.find((b) => b.slug === slug) || { name: slug }).name;

// ---- 04-kit.js
// ساختار کیت: هر کامپوننت یک صفحه، و به‌روزرسانی درجا در اجراهای بعدی
//
// هر صفحه، کامپوننت و آیکونی که پلاگین می‌سازد با pluginData علامت می‌خورد.
// در اجرای بعد (مثلاً با نسخهٔ جدید کاشی) همان گره‌ها پیدا و درجا به‌روز می‌شوند،
// پس instance هایی که در طرح‌ها گذاشته شده‌اند وصل می‌مانند؛ هر چیز جدید هم اضافه می‌شود.

const KEY = { page: "kashi-page", set: "kashi-set", root: "kashi-root" };

/** حاصل‌ضرب دکارتی ویژگی‌ها: { Size: ["sm","md"], State: [...] } → [{Size, State}, ...] */
function combos(axes) {
  return Object.entries(axes).reduce(
    (acc, [k, values]) => acc.flatMap((a) => values.map((v) => Object.assign({}, a, { [k]: v }))),
    [{}],
  );
}

// ---------- ثبت صفحه‌ها ----------
S.groups = [];
S.queue = [];

/** گروه صفحه‌ها (Actions، Forms، ...) که با یک جداکننده در فهرست صفحه‌ها از هم جدا می‌شوند */
function kitPage(emoji, title, titleFa, description) {
  const group = { key: slug(title), emoji, title, titleFa, description };
  S.groups.push(group);
  return group;
}

const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");

/** هر بخش یک صفحهٔ جدا می‌شود: «🔘 Button» */
function section(group, title, description, build, opts) {
  const en = title.split(" · ")[0];
  S.queue.push({ id: `${group.key}/${slug(en)}`, group, title, en, description, build, opts: opts || {} });
}

function setThemeMode(node) {
  const theme = S.collections["Kashi · Theme"];
  if (!theme) return;
  const mode = theme.modes[S.theme === "dark" ? "Dark" : "Light"];
  if (!mode) return;
  try { node.setExplicitVariableModeForCollection(theme.node, mode); } catch (e) { /* API قدیمی */ }
}

/** محتوای یک صفحه را می‌سازد؛ کامپوننت‌های قبلی همان صفحه درجا به‌روز می‌شوند */
function renderSection(item, page) {
  // کامپوننت‌های موجود را کنار می‌گذاریم تا در ساخت تازه دوباره استفاده شوند
  S.existing = {};
  for (const n of page.findAll((x) => (x.type === "COMPONENT" || x.type === "COMPONENT_SET") && !!x.getPluginData(KEY.set))) {
    if (n.type === "COMPONENT" && n.parent && n.parent.type === "COMPONENT_SET") continue;
    S.existing[n.getPluginData(KEY.set)] = n;
  }
  for (const n of Object.values(S.existing)) page.appendChild(n);
  for (const n of page.children.slice()) if (n.getPluginData(KEY.root)) n.remove();

  const stack = !!item.opts.stack;
  const holder = F({ name: "Components", dir: stack ? "V" : "H", wrap: !stack, gap: 32, rowGap: stack ? undefined : 32, w: "fill", cross: "start" });
  const root = F({ name: item.en, dir: "V", gap: 40, p: 64, fill: "bg-primary", minW: 1440 }, [
    F({ name: "Header", dir: "V", gap: 8, w: "fill", pb: 32, stroke: "border-secondary", sides: [0, 0, 1, 0] }, [
      T(`Kashi UI · ${item.group.title}`, { style: "Text sm/Semibold", color: "text-brand" }),
      T(item.title, { style: "Display 3xl/Semibold", color: "text-primary" }),
      item.description && T(item.description, { style: "Text md/Regular", color: "text-tertiary", w: 760 }),
    ]),
    holder,
  ]);
  root.setPluginData(KEY.root, "1");
  page.appendChild(root);
  setThemeMode(root);
  item.build(holder);

  // کامپوننتی که در نسخهٔ جدید حذف شده
  for (const n of Object.values(S.existing)) n.remove();
  S.existing = {};
}

// ---------- به‌روزرسانی درجای کامپوننت ----------
const COPY_FIELDS = [
  "layoutWrap", "primaryAxisAlignItems", "counterAxisAlignItems", "itemSpacing", "paddingTop", "paddingBottom", "paddingLeft", "paddingRight",
  "fills", "strokes", "strokeAlign", "effects", "clipsContent", "opacity", "dashPattern", "topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius",
];
const BIND_FIELDS = ["width", "height", "itemSpacing", "counterAxisSpacing", "paddingTop", "paddingBottom", "paddingLeft", "paddingRight", "topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius"];
const AUTO_LAYOUT_ONLY = /^(layoutWrap|primaryAxis|counterAxis|itemSpacing|padding)/;

/** ظاهر و فرزندان فریم تازه را به کامپوننت موجود منتقل می‌کند؛ شناسهٔ کامپوننت و instance ها می‌مانند */
/** تبدیل فریم به کامپوننت با حفظ برچسب CSS (pluginData در تبدیل حفظ نمی‌شود) */
function toComponent(frame) {
  const css = frame.getPluginData("css");
  const comp = figma.createComponentFromNode(frame);
  if (css) comp.setPluginData("css", css);
  return comp;
}

function updateComponent(comp, frame) {
  // اندازه را قبل از جابه‌جایی فرزندان می‌خوانیم؛ بعدش فریم خالی است
  const w = frame.width, h = frame.height;
  comp.setPluginData("css", frame.getPluginData("css"));
  for (const ch of comp.children.slice()) ch.remove();
  for (const f of BIND_FIELDS) {
    if (comp.boundVariables && comp.boundVariables[f]) { try { comp.setBoundVariable(f, null); } catch (e) { /* */ } }
  }
  comp.layoutMode = frame.layoutMode;
  for (const k of COPY_FIELDS) {
    if (frame.layoutMode === "NONE" && AUTO_LAYOUT_ONLY.test(k)) continue;
    const v = frame[k];
    if (v === figma.mixed || v === undefined) continue;
    try { comp[k] = v; } catch (e) { /* فیلد برای این حالت معنا ندارد */ }
  }
  if (frame.layoutWrap === "WRAP") comp.counterAxisSpacing = frame.counterAxisSpacing;
  if (frame.strokeWeight === figma.mixed) {
    for (const k of ["strokeTopWeight", "strokeRightWeight", "strokeBottomWeight", "strokeLeftWeight"]) comp[k] = frame[k];
  } else comp.strokeWeight = frame.strokeWeight;
  for (const ch of frame.children.slice()) comp.appendChild(ch);
  const sizing = frame.layoutMode !== "NONE" ? [frame.primaryAxisSizingMode, frame.counterAxisSizingMode] : null;
  comp.resize(w, h);
  if (sizing) { comp.primaryAxisSizingMode = sizing[0]; comp.counterAxisSizingMode = sizing[1]; }
  for (const f of BIND_FIELDS) {
    const b = frame.boundVariables && frame.boundVariables[f];
    const v = b && S.varById[b.id];
    if (v) { try { comp.setBoundVariable(f, v); } catch (e) { /* */ } }
  }
  frame.remove();
  return comp;
}

/** کامپوننت تکی با کلید ثابت (آیکون، لوگو): اگر هست درجا به‌روز می‌شود، وگرنه ساخته می‌شود */
function upsertComponent(key, frame) {
  const old = S.existing[key];
  let comp;
  if (old && old.type === "COMPONENT") {
    delete S.existing[key];
    S.stats.updated++;
    comp = updateComponent(old, frame);
  } else {
    comp = toComponent(frame);
    S.stats.added++;
  }
  comp.setPluginData(KEY.set, key);
  return comp;
}

/**
 * یک کامپوننت با variant ها.
 * opts: { axes, build(props) → Frame, text: {Prop: [nodeName, default]}, bools: {Prop: [nodeName, default]}, cols, description, docs }
 */
function componentSet(section, name, opts) {
  const list = opts.axes ? combos(opts.axes) : [{}];
  const variantName = (props) => Object.entries(props).map(([k, v]) => `${k}=${v}`).join(", ");
  const wantSet = !!opts.axes;
  let old = S.existing[name];
  if (old && (old.type === "COMPONENT_SET") !== wantSet) { old.remove(); old = null; }
  delete S.existing[name];

  let node;
  const comps = [];
  if (!wantSet) {
    const frame = opts.build({});
    if (old) { node = updateComponent(old, frame); S.stats.updated++; } else { node = toComponent(frame); S.stats.added++; }
    node.name = name;
    section.appendChild(node);
    comps.push(node);
    S.stats.components++;
  } else {
    const byName = {};
    if (old) for (const c of old.children) byName[c.name] = c;
    for (const props of list) {
      const frame = opts.build(props);
      const vn = variantName(props);
      let comp;
      if (byName[vn]) { comp = updateComponent(byName[vn], frame); delete byName[vn]; } else { comp = toComponent(frame); comp.name = vn; }
      comps.push(comp);
      S.stats.components++;
    }
    if (old) {
      node = old;
      section.appendChild(node);
      for (const c of comps) if (c.parent !== node) node.appendChild(c);
      for (const c of Object.values(byName)) c.remove();
      S.stats.updated++;
    } else {
      for (const c of comps) section.appendChild(c);
      node = figma.combineAsVariants(comps, section);
      S.stats.added++;
    }
    node.name = name;
    layoutVariantGrid(section, node, comps, list, opts);
    S.stats.sets++;
  }
  node.setPluginData(KEY.set, name);
  node.description = opts.description || "";
  if (opts.docs) node.documentationLinks = [{ uri: docsUrl(opts.docs) }];

  // ویژگی‌های متنی و بولی؛ کلید قبلی حفظ می‌شود تا override های instance ها بمانند
  const defs = node.componentPropertyDefinitions || {};
  const wire = (map, type, field) => {
    for (const [prop, [nodeName, def]] of Object.entries(map || {})) {
      let key = Object.keys(defs).find((k) => k.split("#")[0] === prop && defs[k].type === type);
      if (!key) { try { key = node.addComponentProperty(prop, type, def); } catch (e) { continue; } }
      for (const c of comps) {
        for (const n of c.findAll((x) => x.name === nodeName)) {
          try { n.componentPropertyReferences = Object.assign({}, n.componentPropertyReferences, { [field]: key }); } catch (e) { /* داخل instance */ }
        }
      }
    }
  };
  wire(opts.text, "TEXT", "characters");
  wire(opts.bools, "BOOLEAN", "visible");
  return node;
}

/**
 * چیدمان جدولی variant ها: یک ویژگی ستون‌ها (State، بعد Size) و بقیه ردیف‌ها؛
 * برچسب ستون‌ها بالا و برچسب ردیف‌ها سمت راست. ستون اول سمت راست است (RTL).
 */
function layoutVariantGrid(section, node, comps, list, opts) {
  const keys = Object.keys(opts.axes);
  const gap = pick(opts.gap, 24), pad = 32;
  const colKey = opts.colAxis || (keys.includes("State") ? "State" : keys.includes("Size") ? "Size" : keys[keys.length - 1]);
  const rowKeys = keys.filter((k) => k !== colKey);
  let cols, rowOf, colOf, rowLabels, colLabels;
  if (!rowKeys.length) {
    // یک ویژگی با مقدارهای زیاد (مثل بانک‌ها): چند ردیف بدون برچسب
    const widest = Math.max(...comps.map((c) => c.width));
    const n = Math.max(1, Math.min(comps.length, Math.floor((1312 - pad * 2 + gap) / (widest + gap))));
    cols = n;
    colOf = (i) => i % n;
    rowOf = (i) => Math.floor(i / n);
    rowLabels = [];
    colLabels = comps.length <= n ? opts.axes[colKey] : [];
  } else {
    const colValues = opts.axes[colKey];
    cols = colValues.length;
    const rowNames = [];
    rowOf = (i) => {
      const nm = rowKeys.map((k) => list[i][k]).join(" · ");
      let r = rowNames.indexOf(nm);
      if (r < 0) { rowNames.push(nm); r = rowNames.length - 1; }
      return r;
    };
    colOf = (i) => colValues.indexOf(list[i][colKey]);
    list.forEach((_, i) => rowOf(i));
    rowLabels = rowNames;
    colLabels = colValues;
  }
  const rows = Math.max(...comps.map((_, i) => rowOf(i))) + 1;
  const colW = Array(cols).fill(0), rowH = Array(rows).fill(0);
  comps.forEach((c, i) => { colW[colOf(i)] = Math.max(colW[colOf(i)], c.width); rowH[rowOf(i)] = Math.max(rowH[rowOf(i)], c.height); });
  const W = colW.reduce((a, b) => a + b, 0) + gap * (cols - 1) + pad * 2;
  const H = rowH.reduce((a, b) => a + b, 0) + gap * (rows - 1) + pad * 2;
  // x ستون از راست
  const colX = [], rowY = [];
  let x = W - pad;
  for (let c = 0; c < cols; c++) { x -= colW[c]; colX[c] = x; x -= gap; }
  let y = pad;
  for (let r = 0; r < rows; r++) { rowY[r] = y; y += rowH[r] + gap; }

  node.layoutMode = "NONE";
  node.resize(W, H);
  comps.forEach((c, i) => {
    if (c.parent !== node) node.appendChild(c);
    c.x = colX[colOf(i)] + colW[colOf(i)] - c.width;
    c.y = rowY[rowOf(i)] + (rowH[rowOf(i)] - c.height) / 2;
  });
  node.fills = [paint("bg-secondary")];
  node.strokes = [paint("border-secondary")];
  node.dashPattern = [6, 4];
  node.cornerRadius = 16;

  // قاب با برچسب‌ها
  const labelW = rowLabels.length ? 168 : 0;
  const headH = colLabels.length ? 32 : 0;
  const frame = F({ name: `${node.name} · grid`, dir: "none", w: W + labelW, h: H + headH });
  section.appendChild(frame);
  frame.appendChild(node);
  node.x = 0;
  node.y = headH;
  colLabels.forEach((v, c) => {
    const t = T(v, { style: "Text xs/Medium", color: "text-tertiary", ltr: true });
    frame.appendChild(t);
    t.x = colX[c] + colW[c] - t.width;
    t.y = 6;
  });
  rowLabels.forEach((v, r) => {
    const t = T(v, { style: "Text xs/Medium", color: "text-tertiary", ltr: true });
    frame.appendChild(t);
    t.x = W + 16;
    t.y = headH + rowY[r] + (rowH[r] - t.height) / 2;
  });
}

// نام‌هایی که در مستندات صفحهٔ دیگری دارند
const DOC_ALIASES = {
  chip: "chips", chart: "charts", stat: "stat-card", "data-table": "table", kbd: "divider", "relative-time": "persian/utilities",
  "card-number-input": "persian/input", "iban-input": "persian/input", "national-id-input": "persian/input", "mobile-input": "persian/input",
  "price-input": "persian/input", "plate-input": "persian/input", "persian-input": "persian/input", "time-input": "persian/input",
  "province-select": "persian/province", "payment-receipt": "persian/receipt", "bank-badge": "persian/bank-logos",
  calendar: "persian/date-picker", "date-picker": "persian/date-picker", "otp-input": "persian/otp",
};
function docsUrl(name) {
  const base = "https://kashi.sepantapouya.com/docs/";
  const target = DOC_ALIASES[name] || name;
  if (target.includes("/")) return `${base}${target}/`;
  if (TOKENS.docPages.components.includes(target)) return `${base}components/${target}/`;
  if (TOKENS.docPages.persian.includes(target)) return `${base}persian/${target}/`;
  return base;
}

/** ساخت ایمن: خطای یک کامپوننت کل کیت را خراب نکند */
function safe(label, fn) {
  try { fn(); } catch (e) {
    S.errors = S.errors || [];
    S.errors.push(`${label}: ${e && e.message ? e.message : e}`);
  }
}

// ---- 05-foundations.js
// صفحهٔ پایه‌ها: رنگ، تایپوگرافی، فاصله، گردی و سایه

const SCALE_FA = { firoozeh: "فیروزه", lajvard: "لاجورد", zafaran: "زعفران", anar: "انار", pesteh: "پسته", shab: "شب" };

function hexLabel(rgba) {
  const h = (v) => Math.round(v * 255).toString(16).padStart(2, "0");
  return ("#" + h(rgba[0]) + h(rgba[1]) + h(rgba[2])).toUpperCase() + (rgba[3] < 1 ? ` · ${Math.round(rgba[3] * 100)}%` : "");
}

function buildFoundations() {
  const root = kitPage("🎨", "Foundations", "پایه‌ها", "رنگ‌ها، تایپوگرافی، فاصله‌ها، گردی گوشه‌ها و سایه‌ها — همه Variable هستند (بدون Style) و با تغییر mode تیره/روشن، تراکم و گردی عوض می‌شوند.");

  safe("palette", () => section(root, "Colors · پالت رنگ", "رنگ‌های پایه با الهام از کاشی‌کاری ایرانی. کامپوننت‌ها مستقیم از این‌ها استفاده نمی‌کنند؛ از توکن‌های معنایی استفاده می‌کنند.", (h) => {
    for (const [scale, steps] of Object.entries(TOKENS.palette)) {
      const row = F({ name: scale, dir: "V", gap: 8, w: "fill" }, [
        T(`${SCALE_FA[scale] || scale} · ${scale}`, { style: "Text sm/Semibold", color: "text-secondary" }),
        // ردیف‌ها می‌شکنند تا رنگ‌ها از کادر بیرون نزنند
        F({ name: "Swatches", dir: "H", wrap: true, gap: 8, rowGap: 12, w: "fill" }, Object.keys(steps).map((step) =>
          F({ name: step, dir: "V", gap: 4, w: 80 }, [
            R({ w: 80, h: 56, radius: "radius/md", fill: `${scale}/${step}`, stroke: "border-secondary", name: "Swatch" }),
            T(step, { style: "Text xs/Semibold", color: "text-secondary", ltr: true, w: "fill" }),
            T(steps[step].toUpperCase(), { style: "Text xs/Regular", color: "text-quaternary", ltr: true, w: "fill" }),
          ]),
        )),
      ]);
      add(h, row);
    }
  }, { stack: true }));

  safe("semantic", () => section(root, "Semantic colors · رنگ‌های معنایی", "این توکن‌ها در دو mode تیره و روشن مقدار دارند. برای دیدن تم روشن، فریم را انتخاب کنید و از پنل Appearance حالت Light را بزنید.", (h) => {
    const groups = { "پس‌زمینه": "bg-", "متن": "text-", "حاشیه": "border-" };
    for (const [label, prefix] of Object.entries(groups)) {
      const tokens = Object.keys(TOKENS.themes.dark).filter((k) => k.startsWith(prefix));
      const col = F({ name: label, dir: "V", gap: 8, w: 400 }, [
        T(label, { style: "Text sm/Semibold", color: "text-secondary" }),
        ...tokens.map((tk) =>
          F({ name: tk, dir: "H", gap: 12, w: "fill", p: 8, radius: "radius/md", stroke: "border-secondary" }, [
            R({ w: 36, h: 36, radius: "radius/sm", fill: tk, stroke: "border-secondary", name: "Swatch" }),
            F({ dir: "V", gap: 0, grow: true }, [
              T(tk, { style: "Text sm/Medium", color: "text-primary", ltr: true }),
              T(`Dark ${hexLabel(themeRgba(tk, "dark"))}  ·  Light ${hexLabel(themeRgba(tk, "light"))}`, { style: "Text xs/Regular", color: "text-tertiary", ltr: true }),
            ]),
          ]),
        ),
      ]);
      add(h, col);
    }
  }));

  safe("type", () => section(root, "Typography · تایپوگرافی", `فونت پیش‌فرض: ${S.family}. برای استفاده از فونت دیگر (حتی فونت پولی)، متغیر font/family/sans را در مجموعهٔ Kashi · Typography عوض کنید.`, (h) => {
    const col = F({ name: "Type scale", dir: "V", gap: 16, w: "fill" });
    add(h, col);
    applySizing(col);
    for (const base of TYPE_SCALE) {
      const name = `${base}/${base.startsWith("Text") ? "Regular" : "Semibold"}`;
      const spec = typeSpec(name);
      const row = F({ name, dir: "H", gap: 24, w: "fill", cross: "center", pb: 16, stroke: "border-secondary", sides: [0, 0, 1, 0] }, [
        F({ dir: "V", gap: 0, w: 200 }, [
          T(name, { style: "Text sm/Medium", color: "text-secondary", ltr: true }),
          T(`${spec.size}px / ${Math.round(spec.size * spec.leading)}px`, { style: "Text xs/Regular", color: "text-quaternary", ltr: true }),
        ]),
        T("کاشی، دیزاین‌سیستم فارسی ۱۴۰۵", { style: name, color: "text-primary", grow: true }),
      ]);
      add(col, row);
    }
  }, { stack: true }));

  safe("spacing", () => section(root, "Spacing · فاصله‌ها", "مضرب‌های ۴ پیکسل. در auto layout به جای عدد از متغیرهای space استفاده کنید.", (h) => {
    const col = F({ name: "Spacing", dir: "V", gap: 8, w: 520 });
    add(h, col);
    for (const [k, v] of Object.entries(TOKENS.space).sort((a, b) => a[1] - b[1])) {
      if (!v) continue;
      add(col, F({ name: k, dir: "H", gap: 16, w: "fill" }, [
        T(`space/${k}`, { style: "Text sm/Medium", color: "text-secondary", ltr: true, w: 110 }),
        T(`${v}px`, { style: "Text sm/Regular", color: "text-tertiary", ltr: true, w: 60 }),
        R({ w: v, h: 16, radius: 2, fill: "bg-brand", name: "Bar" }),
      ]));
    }
  }));

  safe("radius", () => section(root, "Radius · گردی گوشه‌ها", "مجموعهٔ Kashi · Radius چهار mode دارد: Default، Sharp (تیز)، Soft و Round.", (h) => {
    for (const k of ["none", "sm", "md", "lg", "xl", "2xl", "full"]) {
      add(h, F({ name: k, dir: "V", gap: 8, cross: "center" }, [
        F({ w: 88, h: 88, radius: `radius/${k}`, fill: "bg-tertiary", stroke: "border-primary" }),
        T(`radius/${k}`, { style: "Text sm/Medium", color: "text-secondary", ltr: true }),
        T(k === "full" ? "9999" : `${TOKENS.radius[k]}px`, { style: "Text xs/Regular", color: "text-quaternary", ltr: true }),
      ]));
    }
  }));

  safe("shadow", () => section(root, "Shadows · سایه‌ها", "سایه‌ها برای هر تم جدا تعریف شده‌اند؛ در تم تیره باید پررنگ‌تر باشند تا دیده شوند.", (h) => {
    for (const k of ["xs", "sm", "md", "lg", "xl", "2xl"]) {
      add(h, F({ name: k, dir: "V", gap: 12, cross: "center", p: 24 }, [
        F({ w: 120, h: 88, radius: "radius/lg", fill: "bg-elevated", stroke: "border-secondary", shadow: `Shadow/${k}` }),
        T(`Shadow/${k}`, { style: "Text sm/Medium", color: "text-secondary", ltr: true }),
      ]));
    }
    add(h, F({ name: "focus", dir: "V", gap: 12, cross: "center", p: 24 }, [
      F({ w: 120, h: 44, radius: "radius/md", fill: "bg-primary", stroke: "border-brand", shadow: "Input focus" }),
      T("Focus ring", { style: "Text sm/Medium", color: "text-secondary", ltr: true }),
    ]));
  }));
}

// ---- 10-actions.js
// دکمه‌ها و کنترل‌های عملیاتی

const BTN_VARIANTS = {
  Primary: { bg: "bg-brand", hover: "bg-brand-hover", fg: "text-on-brand", shadow: true },
  Secondary: { bg: "bg-elevated", overlay: true, fg: "text-secondary", hoverFg: "text-primary", border: "border-primary", shadow: true },
  Tertiary: { overlay: true, fg: "text-secondary", hoverFg: "text-primary", ghost: true },
  Link: { fg: "text-brand", link: true },
  Danger: { bg: "bg-error", hover: "bg-error-hover", fg: "text-on-error", shadow: true, danger: true },
  "Danger secondary": { bg: "bg-elevated", overlay: true, fg: "text-error", border: "border-primary", shadow: true, danger: true },
};
const BTN_FONT = { xs: "Text xs/Semibold", sm: "Text sm/Semibold", md: "Text sm/Semibold", lg: "Text md/Semibold", xl: "Text md/Semibold" };
const BTN_ICON = { xs: 16, sm: 18, md: 20, lg: 20, xl: 20 };

/** دکمهٔ کاشی؛ در بقیهٔ کامپوننت‌ها هم استفاده می‌شود */
function button({ variant = "Secondary", size = "md", state = "Default", label = "ثبت", iconStart, iconEnd, iconOnly, pill, w } = {}) {
  const v = BTN_VARIANTS[variant];
  const disabled = state === "Disabled";
  const hover = state === "Hover";
  const focus = state === "Focus";
  let fg = v.fg;
  const fills = [];
  if (disabled && !v.link) {
    fg = "text-quaternary";
    if (!v.ghost) fills.push("bg-secondary");
  } else {
    if (hover && v.hover) fills.push(v.hover);
    else if (v.bg) fills.push(v.bg);
    if (hover && v.overlay) fills.push("bg-hover");
    if (hover && v.hoverFg) fg = v.hoverFg;
  }
  if (disabled && v.link) fg = "text-quaternary";
  const iconSize = BTN_ICON[size];
  const kids = [];
  if (iconOnly) kids.push(I(iconOnly, iconSize, fg));
  else {
    const s = I(iconStart || "plus", iconSize, fg); s.name = "Icon start"; s.visible = !!iconStart; kids.push(s);
    kids.push(T(label, { style: BTN_FONT[size], color: fg, name: "Label", decoration: v.link && hover ? "UNDERLINE" : undefined }));
    const e = I(iconEnd || "arrow-left", iconSize, fg); e.name = "Icon end"; e.visible = !!iconEnd; kids.push(e);
  }
  let shadow;
  if (!disabled && v.shadow) shadow = focus ? (v.danger ? "Button danger focus" : "Button focus") : "Button";
  else if (focus && !v.shadow) shadow = v.danger ? "Focus ring/error" : "Focus ring/brand";
  else if (disabled && v.shadow) shadow = "Shadow/xs";
  const f = F({
    name: "Button",
    dir: "H",
    gap: size === "xs" ? "space/1" : "space/1.5",
    // دکمهٔ گرد ۴ پیکسل فاصلهٔ بیشتر دارد (k-btn--pill)
    px: v.link ? 0 : iconOnly ? 0 : pill ? numOf(`control/padding/${size}`) + 4 : `control/padding/${size}`,
    h: v.link ? undefined : `control/height/${size}`,
    w: iconOnly ? `control/height/${size}` : w,
    align: "center",
    cross: "center",
    radius: pill ? "radius/full" : "radius/md",
    stroke: v.border ? (disabled ? "border-secondary" : v.border) : undefined,
    shadow,
  }, kids);
  f.fills = fills.map((c) => paint(c));
  // فقط حالت پیش‌فرض با CSS اندازه‌گیری‌شده مقایسه می‌شود
  if (state === "Default" && !w) {
    const cls = ["k-btn", `k-btn--${variant.toLowerCase().replace(" ", "-")}`, size !== "md" && `k-btn--${size}`, iconOnly && "k-btn--icon", pill && "k-btn--pill"].filter(Boolean).sort().join(" ");
    tagCss(f, { css: cls, cssCheck: iconOnly ? ["radius", "bg", "border", "h", "w"] : v.link ? ["bg"] : ["padx", "radius", "gap", "bg", "border", "h"] });
  }
  return f;
}

function buildActions() {
  const root = kitPage("🔘", "Actions", "دکمه‌ها و عملیات", "دکمه با سایهٔ اسکئومورفیک و حلقهٔ فوکوس نرم به سبک Untitled UI. ارتفاع و فاصلهٔ داخلی به مجموعهٔ Kashi · Density وصل است.");

  safe("Button", () => section(root, "Button · دکمه", "شش گونه، پنج اندازه و چهار حالت. متن، آیکون ابتدا و انتها از پنل ویژگی‌ها قابل تغییر است.", (h) => {
    componentSet(h, "Button", {
      axes: { Variant: Object.keys(BTN_VARIANTS), Size: ["xs", "sm", "md", "lg", "xl"], State: ["Default", "Hover", "Focus", "Disabled"] },
      build: (p) => button({ variant: p.Variant, size: p.Size, state: p.State }),
      text: { Label: ["Label", "ثبت"] },
      bools: { "Icon start": ["Icon start", false], "Icon end": ["Icon end", false] },
      cols: 20,
      gap: 16,
      description: "دکمهٔ کاشی — <Button variant size>. در React: import { Button } from \"@kashi-ui/react\"",
      docs: "button",
    });
  }));

  safe("IconButton", () => section(root, "Icon button · دکمهٔ آیکونی", "دکمهٔ مربعی فقط با آیکون. حتماً در کد aria-label بدهید.", (h) => {
    componentSet(h, "Icon button", {
      axes: { Variant: ["Primary", "Secondary", "Tertiary"], Size: ["sm", "md", "lg"], State: ["Default", "Hover", "Disabled"], Shape: ["Square", "Pill"] },
      build: (p) => button({ variant: p.Variant, size: p.Size, state: p.State, iconOnly: "plus", pill: p.Shape === "Pill" }),
      cols: 18,
      gap: 16,
      docs: "button",
    });
  }));

  safe("ButtonGroup", () => section(root, "Button group · گروه دکمه", "چند دکمهٔ چسبیده برای انتخاب یا عملیات مرتبط.", (h) => {
    componentSet(h, "Button group", {
      axes: { Size: ["sm", "md"] },
      build: (p) => {
        const items = ["روز", "هفته", "ماه", "سال"];
        const f = F({ name: "Button group", dir: "H", gap: 0, radius: "radius/md", stroke: "border-primary", clip: true, shadow: "Shadow/xs", fill: "bg-elevated" },
          items.map((label, i) =>
            F({ name: "Item", dir: "H", h: `control/height/${p.Size}`, px: `control/padding/${p.Size}`, cross: "center", fill: i === 1 ? "bg-active" : undefined, stroke: i < items.length - 1 ? "border-primary" : undefined, sides: [0, 0, 0, 1] }, [
              T(label, { style: "Text sm/Semibold", color: i === 1 ? "text-primary" : "text-secondary" }),
            ]),
          ));
        return f;
      },
      docs: "button-group",
    });
  }));

  safe("Segmented", () => section(root, "Segmented control · کنترل بخش‌بندی", "انتخاب یکی از چند گزینه؛ مثل تب کوچک.", (h) => {
    componentSet(h, "Segmented control", {
      axes: { Size: ["sm", "md"], Selected: ["1", "2", "3"] },
      build: (p) => {
        const items = ["فهرست", "جدول", "نقشه"];
        // k-segmented: فاصلهٔ ۳، گوشهٔ ۱۲؛ هر بخش ۳۲ (کوچک ۲۸) با گوشهٔ ۹
        return F({ name: "Segmented", dir: "H", gap: 2, p: 3, radius: 12, fill: "bg-secondary", stroke: "border-secondary", css: p.Size === "sm" ? "k-segmented k-segmented--sm" : "k-segmented" },
          items.map((label, i) => {
            const on = String(i + 1) === p.Selected;
            return F({ name: "Segment", dir: "H", gap: "space/1.5", h: p.Size === "sm" ? 28 : 32, px: "space/3", cross: "center", radius: 9, fill: on ? "bg-elevated" : undefined, shadow: on ? "Shadow/sm" : undefined, css: on ? undefined : "k-segmented__item", cssCheck: ["padx", "radius", "gap", "bg"] }, [
              T(label, { style: "Text sm/Semibold", color: on ? "text-primary" : "text-tertiary", css: on ? undefined : "k-segmented__item" }),
            ]);
          }));
      },
      docs: "segmented-control",
    });
  }));

  safe("Copy", () => section(root, "Copy button · دکمهٔ کپی", "کپی در کلیپ‌بورد با بازخورد «کپی شد».", (h) => {
    componentSet(h, "Copy button", {
      axes: { State: ["Idle", "Copied"] },
      build: (p) => {
        const f = button({ variant: "Secondary", size: "sm", label: p.State === "Idle" ? "کپی" : "کپی شد", iconStart: p.State === "Idle" ? "copy" : "check" });
        if (p.State === "Copied") for (const n of f.findAll((x) => x.type === "TEXT")) n.fills = [paint("text-success")];
        return f;
      },
      docs: "copy-button",
    });
  }));
}

// ---- 11-forms.js
// فرم‌ها: فیلد، انتخاب، چک‌باکس، سوییچ، اسلایدر، تقویم و ...

const FIELD_W = 320;

/** کادر فیلد ورودی */
function inputBox({ size = "md", state = "Default", text = "", placeholder = "متن را وارد کنید", iconStart, end = [], start = [], w = "fill", h, ltr, name = "Input" } = {}) {
  const disabled = state === "Disabled";
  const error = state === "Error";
  const focus = state === "Focus";
  const stroke = disabled ? "border-secondary" : focus ? "border-brand" : error ? "border-error" : state === "Hover" ? "text-quaternary" : "border-input";
  const shadow = focus ? (error ? "Input error focus" : "Input focus") : "Shadow/xs";
  const valueColor = disabled ? "text-quaternary" : text ? "text-primary" : "text-quaternary";
  const kids = [];
  if (iconStart) kids.push(I(iconStart, 20, "text-quaternary"));
  kids.push(...start);
  kids.push(T(text || placeholder, { style: "Text md/Regular", color: valueColor, name: "Value", grow: true, ltr, w: "fill", maxLines: 1, css: "k-input__control", cssCheck: ["font"] }));
  kids.push(...end);
  const plain = state === "Default" && !h;
  return F({
    name, dir: "H", gap: "space/2", px: "input/padding", h: h || `input/height/${size}`, w, cross: "center",
    radius: "radius/md", fill: disabled ? "bg-secondary" : "bg-primary", stroke, shadow,
    css: plain && size !== "lg" ? (size === "sm" ? "k-input k-input--sm" : "k-input") : undefined, cssCheck: ["padx", "radius", "gap", "bg", "border", "h"],
  }, kids);
}

/** برچسب، کنترل و متن راهنما */
function field({ label = "برچسب", hint, error, optional, required, control, w = FIELD_W, labelEnd }) {
  // برچسب و راهنما در CSS خط ۱٫۳۵ دارند (k-label، k-hint)
  const labelRow = F({ name: "Label row", dir: "H", gap: "space/3", w: "fill", cross: "center", css: "k-field__label-row", cssCheck: ["gap"] }, [
    F({ name: "Label group", dir: "H", gap: "space/1", cross: "center" }, [
      T(label, { style: "Tight sm/Medium", color: "text-secondary", name: "Label", css: "k-label" }),
      required && T("*", { style: "Tight sm/Medium", color: "text-error", name: "Required", css: "k-label__required" }),
      optional && T("اختیاری", { style: "Tight sm/Regular", color: "text-tertiary", name: "Optional", css: "k-label__optional" }),
    ]),
    labelEnd && Spacer(),
    labelEnd,
  ]);
  const hintNode = (hint || error) && F({ name: "Hint row", dir: "H", gap: "space/3", w: "fill", cross: "start", css: "k-field__hint-row", cssCheck: ["gap"] }, [
    T(error || hint, { style: "Tight sm/Regular", color: error ? "text-error" : "text-tertiary", name: "Hint", grow: true, w: "fill", css: error ? "k-hint k-hint--error" : "k-hint" }),
  ]);
  return F({ name: "Field", dir: "V", gap: "space/1.5", w, css: "k-field", cssCheck: ["gap"] }, [labelRow, control, hintNode]);
}

/** پنل فهرست کشویی (Listbox / Menu) */
function listbox(items, { w = FIELD_W, active = 1, selected = 0, query } = {}) {
  return F({ name: "Listbox", dir: "V", gap: 0, p: "space/1.5", w, radius: "radius/lg", fill: "bg-elevated", stroke: "border-secondary", shadow: "Popover" },
    items.map((it, i) => {
      const o = typeof it === "string" ? { label: it } : it;
      if (o.group) return T(o.group, { style: "Text xs/Semibold", color: "text-tertiary", name: "Group", w: "fill" });
      const on = i === selected;
      // گزینهٔ دوخطی ارتفاع ثابت ندارد تا متن‌ها روی هم نیفتند
      // k-option: حداقل ۴۰ پیکسل؛ گزینهٔ دوخطی بلندتر می‌شود
      return F({ name: "Option", dir: "H", gap: "space/2", h: o.description ? undefined : 40, minH: 40, py: o.description ? 6 : undefined, px: 10, w: "fill", cross: "center", radius: "radius/md", fill: i === active ? "bg-hover" : undefined, css: i === active && !o.description ? "k-option" : undefined, cssCheck: ["padx", "radius", "gap", "bg", "h"] }, [
        o.icon && I(o.icon, 18, "text-tertiary"),
        o.logo && bankLogo(o.logo, 20),
        F({ name: "Body", dir: "V", gap: 0, grow: true }, [
          // بخش منطبق در همان یک متن رنگی می‌شود تا اتصال حروف فارسی نشکند
          T(o.label, { style: on ? "Text sm/Semibold" : "Text sm/Regular", color: o.disabled ? "text-quaternary" : on || i === active ? "text-primary" : "text-secondary", name: "Label", highlight: query && o.label.includes(query) ? [o.label.indexOf(query), o.label.indexOf(query) + query.length] : undefined }),
          o.description && T(o.description, { style: "Text xs/Regular", color: "text-tertiary", css: "k-option__desc" }),
        ]),
        o.shortcut && T(o.shortcut, { style: "Text xs/Regular", color: "text-quaternary", ltr: true }),
        on && I("check", 16, "text-brand"),
      ]);
    }));
}

/** برچسب داخل TagInput و MultiSelect؛ در React همان Badge قابل حذف است */
function tag(label, { tone = "Neutral" } = {}) {
  return badge({ tone, label, dot: false, removable: true });
}

/** کادر چندبرچسبی (k-tag-input) */
function tagBox({ state = "Default", tags = [], placeholder = "", end = [] }) {
  const focus = state === "Focus";
  return F({ name: "Tag input", dir: "H", wrap: true, gap: "space/1.5", rowGap: "space/1.5", py: 6, px: 10, w: "fill", minH: 40, cross: "center",
    radius: "radius/md", fill: "bg-primary", stroke: focus ? "border-brand" : "border-input", shadow: focus ? "Input focus" : "Shadow/xs",
    css: focus ? undefined : "k-tag-input" }, [
    ...tags,
    F({ name: "Control", dir: "H", p: 4, grow: true, cross: "center", css: "k-tag-input__control", cssCheck: ["pad"] }, [T(placeholder || " ", { style: "Text md/Regular", color: "text-quaternary", name: "Placeholder" })]),
    ...end,
  ]);
}

function checkMark(kind, { checked, state = "Default", size = 18 }) {
  const disabled = state === "Disabled";
  const on = checked && checked !== "Off";
  const isRadio = kind === "radio";
  const fill = disabled ? "bg-tertiary" : on ? (state === "Hover" ? "bg-brand-hover" : "bg-brand") : "bg-elevated";
  const stroke = disabled ? "border-secondary" : on ? fill : state === "Hover" ? "border-brand" : "border-input";
  // در CSS چک‌باکس و رادیو سایهٔ xs دارند؛ در فوکوس حلقهٔ برند هم اضافه می‌شود
  const shadow = state === "Focus" ? "Input focus" : disabled ? undefined : "Shadow/xs";
  const box = F({ name: isRadio ? "Radio" : "Checkbox", dir: "H", w: size, h: size, align: "center", cross: "center", radius: isRadio ? "radius/full" : "radius/checkbox", fill, stroke, shadow,
    css: on && state === "Default" && checked !== "Indeterminate" ? (isRadio ? "k-radio" : size === 20 ? "k-checkbox k-checkbox--lg" : "k-checkbox") : undefined, cssCheck: ["radius", "bg", "border", "h", "w"] }, [
    on && (isRadio
      ? R({ ellipse: true, w: size * 0.4, h: size * 0.4, fill: disabled ? "text-quaternary" : "text-on-brand", name: "Dot" })
      : checked === "Indeterminate"
        ? R({ w: size * 0.55, h: 2, radius: 1, fill: disabled ? "text-quaternary" : "text-on-brand", name: "Dash" })
        : I("check", size * 0.8, disabled ? "text-quaternary" : "text-on-brand")),
  ]);
  return box;
}

function switchTrack({ checked, state = "Default", size = "md" }) {
  const [w, h] = { sm: [28, 16], md: [36, 20], lg: [44, 24] }[size];
  const on = checked === "On";
  const disabled = state === "Disabled";
  const track = disabled ? "bg-tertiary" : on ? (state === "Hover" ? "bg-brand-hover" : "bg-brand") : state === "Hover" ? "text-quaternary" : "border-input";
  return F({ name: "Switch", dir: "H", w, h, p: 2, cross: "center", align: on ? "end" : "start", radius: "radius/full", fill: track, shadow: state === "Focus" ? "Focus ring/brand" : undefined,
    css: on && state === "Default" ? ({ sm: "k-switch k-switch--sm", md: "k-switch", lg: "k-switch k-switch--lg" })[size] : undefined, cssCheck: ["pad", "radius", "bg", "h", "w"] }, [
    R({ ellipse: true, w: h - 4, h: h - 4, fill: disabled ? "bg-secondary" : "#ffffff", shadow: "Shadow/sm", name: "Thumb" }),
  ]);
}

function checkRow(control, { label = "مرا به خاطر بسپار", description = "تا ۳۰ روز وارد حساب بمانید.", disabled } = {}) {
  // k-check: متن با خط ثابت ۲۰ پیکسل و کنترل وسط خط اول
  return F({ name: "Check", dir: "H", gap: "space/2", cross: "start", css: "k-check", cssCheck: ["gap"] }, [
    F({ name: "Control wrap", dir: "H", h: 20, cross: "center" }, [control]),
    F({ name: "Text", dir: "V", gap: 2, css: "k-check__text", cssCheck: ["gap"] }, [
      T(label, { style: "Control sm/Medium", color: disabled ? "text-quaternary" : "text-secondary", name: "Label", css: disabled ? undefined : "k-check__label" }),
      T(description, { style: "Control sm/Regular", color: "text-tertiary", name: "Description", css: "k-check__description" }),
    ]),
  ]);
}

function jalaliGrid({ range, selected = 6, w = 300 } = {}) {
  const C = TOKENS.calendar;
  // k-calendar__day: ۴۰ پیکسل، خانهٔ جدول با ۱ پیکسل فاصله
  const cell = 42;
  const cells = [];
  const lead = C.firstWeekday;
  for (let i = 0; i < lead; i++) cells.push({ day: C.prevLength - lead + 1 + i, out: true });
  for (let d = 1; d <= C.length; d++) cells.push({ day: d });
  while (cells.length % 7) cells.push({ day: cells.length - lead - C.length + 1, out: true });
  const rows = [];
  for (let r = 0; r < cells.length / 7; r++) {
    rows.push(F({ name: "Week", dir: "H", gap: 0 }, cells.slice(r * 7, r * 7 + 7).map((c, i) => {
      const inRange = range && !c.out && c.day >= range[0] && c.day <= range[1];
      const edge = range ? !c.out && (c.day === range[0] || c.day === range[1]) : !c.out && c.day === selected;
      const holiday = !c.out && C.holidays.includes(c.day);
      const today = !c.out && c.day === 6;
      return F({ name: "Day", dir: "H", w: cell, h: cell, align: "center", cross: "center", fill: inRange ? "bg-brand-subtle" : undefined, radius: range && edge ? (c.day === range[0] ? ["radius/full", 0, 0, "radius/full"] : [0, "radius/full", "radius/full", 0]) : undefined }, [
        F({ name: "Cell", dir: "V", w: 40, h: 40, align: "center", cross: "center", radius: "radius/full", fill: edge ? "bg-brand" : undefined, shadow: edge ? "Button" : undefined }, [
          T(fa(c.day), { style: edge ? "Text sm/Semibold" : today ? "Text sm/Bold" : "Text sm/Regular", color: edge ? "text-on-brand" : c.out ? "text-quaternary" : today ? "text-brand" : holiday ? "text-error" : inRange ? "text-primary" : "text-secondary", align: "center" }),
          // امروز: نقطهٔ ۴ پیکسلی زیر عدد
          today && !edge && R({ ellipse: true, w: 4, h: 4, fill: "text-brand", name: "Today dot", absolute: true, x: 18, y: 31 }),
        ]),
      ]);
    })));
  }
  const select = (label) => F({ name: "Select", dir: "H", gap: "space/1", h: 36, ps: "space/3", pe: "space/1.5", cross: "center", radius: "radius/md" }, [
    T(label, { style: "Text sm/Semibold", color: "text-primary" }),
    I("chevron-down", 16, "text-quaternary"),
  ]);
  // همان ساختار k-datepicker__popover و k-calendar در React
  return F({ name: "Calendar", dir: "V", gap: "space/2", p: "space/4", radius: "radius/xl", fill: "bg-elevated", stroke: "border-secondary", shadow: "Popover" }, [
    F({ name: "Header", dir: "H", gap: "space/2", w: "fill", align: "between", cross: "center" }, [
      button({ variant: "Tertiary", size: "sm", iconOnly: "chevron-right" }),
      F({ name: "Selects", dir: "H", gap: "space/1" }, [select(C.months[C.month - 1]), select(fa(C.year))]),
      button({ variant: "Tertiary", size: "sm", iconOnly: "chevron-left" }),
    ]),
    F({ name: "Grid", dir: "V", gap: 0 }, [
      F({ name: "Weekdays", dir: "H", gap: 0 }, C.weekdays.map((d, i) =>
        F({ dir: "H", w: cell, h: 32, align: "center", cross: "center" }, [T(d, { style: "Text xs/Medium", color: i === 6 ? "text-error" : "text-tertiary", align: "center" })]),
      )),
      F({ name: "Days", dir: "V", gap: 0 }, rows),
    ]),
    F({ name: "Footer", dir: "H", w: "fill", align: "center", pt: "space/2", stroke: "border-secondary", sides: [1, 0, 0, 0] }, [
      button({ variant: "Link", label: "امروز" }),
    ]),
  ]);
}

